"""Loading CSV files into tables.

A table is a list of header names exactly as written in the file plus a list
of rows.  Rows are dictionaries keyed by the lower-case header name; column
lookups in queries are case-insensitive (see SPEC.md).
"""

import csv
import os
import re

from .errors import QueryError

_INT_RE = re.compile(r"-?[0-9]+")
_DECIMAL_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


class Table:
    """A loaded CSV table.

    ``columns`` keeps the header spelling; ``rows`` maps lower-case column
    names to values.
    """

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)


def _convert(field):
    """Convert one CSV field to a Python value (SPEC.md's table rules)."""
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def load(directory, name):
    """Load ``<directory>/<name>.csv`` and return a :class:`Table`."""
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, "r", encoding="utf-8", newline="") as handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                # A completely empty file has no columns and no rows.
                return Table([], [])
            raw_rows = list(reader)
    except (OSError, UnicodeDecodeError) as exc:
        raise QueryError(
            "cannot read table %r from %r: %s" % (name, path, exc)
        )

    # csv yields a blank line as an empty list.  A blank line at the end of
    # the file is not a row; blank fields ([""]) still are, and become NULLs.
    while raw_rows and raw_rows[-1] == []:
        raw_rows.pop()

    lower_names = [column.lower() for column in header]
    rows = []
    for fields in raw_rows:
        values = [_convert(field) for field in fields]
        if len(values) < len(lower_names):
            values.extend([None] * (len(lower_names) - len(values)))
        row = {}
        for index, key in enumerate(lower_names):
            row[key] = values[index]
        rows.append(row)

    return Table(header, rows)

"""Query execution: turn an ``ast.Select`` into output columns and rows."""

import functools

from . import ast, expr
from .errors import QueryError
from .table import load


def execute(sql, directory="."):
    """Parse and run ``sql`` against the CSV files in ``directory``."""
    from . import parser

    return execute_select(parser.parse(sql), directory)


def _header_map(table):
    """Map lower-case header names to the spelling used in the file."""
    mapping = {}
    for header in table.columns:
        mapping[header.lower()] = header
    return mapping


def _resolve(node, mapping):
    """Check that every column reference in ``node`` exists in the table."""
    if node is None:
        return
    for sub in ast.walk(node):
        if isinstance(sub, ast.ColumnRef):
            if sub.name.lower() not in mapping:
                raise QueryError("unknown column: %s" % sub.name)


def _select_items(stmt, table):
    """Expand a lone ``*`` select item; reject ``*`` anywhere else."""
    items = stmt.items
    if len(items) == 1 and isinstance(items[0].expr, ast.Star):
        expanded = []
        for header in table.columns:
            ref = ast.ColumnRef(header, header)
            expanded.append(ast.SelectItem(ref, None, header))
        return expanded
    for item in items:
        if isinstance(item.expr, ast.Star):
            raise QueryError("'*' is only allowed as the only select item")
    return list(items)


def _output_name(item, mapping):
    if item.alias is not None:
        return item.alias
    if isinstance(item.expr, ast.ColumnRef):
        return mapping[item.expr.name.lower()]
    return item.expr.text


def _is_ordinal(node):
    return (
        isinstance(node, ast.Literal)
        and isinstance(node.value, int)
        and not isinstance(node.value, bool)
    )


def _output_index(name, output_names):
    wanted = name.lower()
    for index, output_name in enumerate(output_names):
        if output_name.lower() == wanted:
            return index
    return None


def _prepare_order(stmt, output_names, mapping):
    """Classify ORDER BY items and resolve columns.

    Returns (specs, order items) where each spec is ``(kind, data, item)``:
    ``kind`` is ``"ordinal"`` (data is a zero-based output index),
    ``"output"`` (data is a zero-based output index), or ``"expr"`` (data is
    the expression to evaluate on the input row or group).
    """
    specs = []
    for item in stmt.order_by:
        node = item.expr
        if _is_ordinal(node):
            position = node.value
            if position <= 0 or position > len(output_names):
                raise QueryError(
                    "ORDER BY position %d is out of range" % position
                )
            specs.append(("ordinal", position - 1, item))
            continue
        if isinstance(node, ast.ColumnRef):
            index = _output_index(node.name, output_names)
            if index is not None:
                specs.append(("output", index, item))
                continue
        _resolve(node, mapping)
        specs.append(("expr", node, item))
    return specs


def _collect_aggregates(expressions):
    """All distinct aggregate FuncCall nodes, deduplicated by identity."""
    nodes = []
    seen = set()
    for expression in expressions:
        if expression is None:
            continue
        for node in expr.iter_aggregates(expression):
            if id(node) not in seen:
                seen.add(id(node))
                nodes.append(node)
    return nodes


def execute_select(stmt, directory="."):
    """Run a parsed ``SELECT`` and return ``(output_names, rows)``."""
    table = load(directory, stmt.table)
    mapping = _header_map(table)
    items = _select_items(stmt, table)

    # Resolve column references.  ORDER BY gets special treatment: a bare
    # name may refer to an output column (including an alias) instead of a
    # table column, so it is handled after output names are known.
    for item in items:
        _resolve(item.expr, mapping)
    _resolve(stmt.where, mapping)
    for group_expr in stmt.group_by:
        _resolve(group_expr, mapping)
    _resolve(stmt.having, mapping)

    output_names = [_output_name(item, mapping) for item in items]
    order_specs = _prepare_order(stmt, output_names, mapping)

    # Validate functions, argument counts, star placement and aggregates.
    for item in items:
        expr.validate(item.expr, allow_aggregates=True)
    if stmt.where is not None:
        expr.validate(stmt.where, allow_aggregates=False)
    for group_expr in stmt.group_by:
        expr.validate(group_expr, allow_aggregates=False)
    if stmt.having is not None:
        expr.validate(stmt.having, allow_aggregates=True)
    for item in stmt.order_by:
        expr.validate(item.expr, allow_aggregates=True)

    grouped = bool(stmt.group_by)
    if not grouped:
        grouped = any(expr.has_aggregate(item.expr) for item in items)
    if not grouped and stmt.having is not None:
        grouped = expr.has_aggregate(stmt.having)
    if not grouped:
        grouped = any(expr.has_aggregate(item.expr) for item in stmt.order_by)

    # In a grouped query, non-aggregate columns must be GROUP BY expressions.
    if grouped:
        group_keys = {ast.expr_key(group_expr) for group_expr in stmt.group_by}
        for item in items:
            expr.check_grouped(item.expr, group_keys)
        if stmt.having is not None:
            expr.check_grouped(stmt.having, group_keys)
        for kind, _data, item in order_specs:
            # Ordinals and output-column references do not refer to input
            # columns, so the GROUP BY rule does not apply to them.
            if kind == "expr":
                expr.check_grouped(item.expr, group_keys)

    aggregate_nodes = _collect_aggregates(
        [item.expr for item in items]
        + ([stmt.having] if stmt.having is not None else [])
        + [item.expr for item in stmt.order_by]
    )

    # WHERE keeps only rows where the condition is TRUE.
    rows = []
    for row in table.rows:
        if stmt.where is not None:
            value = expr.evaluate(
                stmt.where, expr.EvalContext(columns=row)
            )
            if expr.truth(value) is not True:
                continue
        rows.append(row)

    # Build the units that produce output rows: (context row, group rows,
    # is grouped).  Ungrouped queries have one unit per surviving row.
    if grouped:
        if stmt.group_by:
            groups = {}
            group_order = []
            for row in rows:
                context = expr.EvalContext(columns=row)
                key = tuple(
                    expr.evaluate(group_expr, context)
                    for group_expr in stmt.group_by
                )
                bucket = groups.get(key)
                if bucket is None:
                    bucket = []
                    groups[key] = bucket
                    group_order.append(key)
                bucket.append(row)
            units = [
                (groups[key][0], groups[key], True) for key in group_order
            ]
        else:
            # One group even when there are no rows.
            units = [(rows[0] if rows else {}, rows, True)]
    else:
        units = [(row, None, False) for row in rows]

    records = []
    for context_row, group_rows, is_grouped in units:
        aggregates = {}
        if is_grouped:
            for node in aggregate_nodes:
                aggregates[id(node)] = expr.compute_aggregate(node, group_rows)
        context = expr.EvalContext(columns=context_row, aggregates=aggregates)
        values = tuple(expr.evaluate(item.expr, context) for item in items)

        if stmt.having is not None:
            condition = expr.evaluate(stmt.having, context)
            if expr.truth(condition) is not True:
                continue

        keys = []
        for kind, data, _item in order_specs:
            if kind == "expr":
                keys.append(expr.evaluate(data, context))
            else:
                keys.append(values[data])
        records.append((values, keys))

    # DISTINCT drops repeated output rows, keeping the first.
    if stmt.distinct:
        deduplicated = []
        seen = set()
        for values, keys in records:
            if values in seen:
                continue
            seen.add(values)
            deduplicated.append((values, keys))
        records = deduplicated

    # Sorting: stable, multiple keys, NULLs first ascending / last descending.
    if order_specs:
        descending = [item.descending for _kind, _data, item in order_specs]

        def compare(left, right):
            left_keys = left[1]
            right_keys = right[1]
            for index, desc in enumerate(descending):
                a = left_keys[index]
                b = right_keys[index]
                if a is None and b is None:
                    continue
                if a is None:
                    return 1 if desc else -1
                if b is None:
                    return -1 if desc else 1
                result = expr.compare_values(a, b)
                if result:
                    return -result if desc else result
            return 0

        records = sorted(records, key=functools.cmp_to_key(compare))

    # LIMIT / OFFSET apply after sorting.
    offset = 0 if stmt.offset is None else stmt.offset
    limit = stmt.limit
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise QueryError("OFFSET must be a non-negative integer")
    if limit is not None and (
        not isinstance(limit, int) or isinstance(limit, bool) or limit < 0
    ):
        raise QueryError("LIMIT must be a non-negative integer")

    if offset:
        records = records[offset:]
    if limit is not None:
        records = records[:limit]

    return output_names, [values for values, _keys in records]

"""Temporary stand-in for minisql/expr.py, written strictly to INTERFACES.md.

Used only to exercise engine.py while the real expr.py is being written.
"""

import math
import re

from . import ast
from .errors import QueryError

AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})

_SCALAR_ARITY = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


class EvalContext:
    def __init__(self, columns=None, aggregates=None):
        self.columns = columns or {}
        self.aggregates = aggregates or {}


def truth(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    raise QueryError("condition is not a boolean: %r" % (value,))


def _number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def compare_values(a, b):
    if a is None or b is None:
        raise QueryError("cannot compare NULL with compare_values")
    if isinstance(a, bool) or isinstance(b, bool):
        if isinstance(a, bool) and isinstance(b, bool):
            return (a > b) - (a < b)
        raise QueryError("cannot compare boolean and non-boolean")
    if _number(a) and _number(b):
        return (a > b) - (a < b)
    if isinstance(a, str) and isinstance(b, str):
        return (a > b) - (a < b)
    raise QueryError("cannot compare %r and %r" % (a, b))


def like(value, pattern):
    parts = []
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    return re.fullmatch("".join(parts), value) is not None


def to_concat_text(value):
    return str(value)


def _arith(op, left, right):
    if not _number(left) or not _number(right):
        raise QueryError("arithmetic on non-numbers")
    if op == "/":
        if right == 0:
            return None
        return left / right
    if isinstance(left, int) and isinstance(right, int):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        return left * right
    if op == "+":
        return float(left) + float(right)
    if op == "-":
        return float(left) - float(right)
    return float(left) * float(right)


def _round_away(value):
    if value >= 0:
        return int(math.floor(value + 0.5))
    return -int(math.floor(-value + 0.5))


def evaluate(node, ctx):
    if isinstance(node, ast.Literal):
        return node.value
    if isinstance(node, ast.ColumnRef):
        key = node.name.lower()
        if key not in ctx.columns:
            raise QueryError("unknown column: %s" % node.name)
        return ctx.columns[key]
    if isinstance(node, ast.Star):
        raise QueryError("'*' is not valid here")
    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand, ctx)
        if node.op == "NOT":
            value = truth(value)
            return None if value is None else not value
        if value is None:
            return None
        if not _number(value):
            raise QueryError("unary minus on non-number")
        return -value
    if isinstance(node, ast.BinaryOp):
        op = node.op
        if op in ("AND", "OR"):
            left = truth(evaluate(node.left, ctx))
            right = truth(evaluate(node.right, ctx))
            if op == "AND":
                if left is False or right is False:
                    return False
                if left is None or right is None:
                    return None
                return True
            if left is True or right is True:
                return True
            if left is None or right is None:
                return None
            return False
        if op == "||":
            left = evaluate(node.left, ctx)
            right = evaluate(node.right, ctx)
            if left is None or right is None:
                return None
            return to_concat_text(left) + to_concat_text(right)
        left = evaluate(node.left, ctx)
        right = evaluate(node.right, ctx)
        if left is None or right is None:
            return None
        if op in ("+", "-", "*", "/"):
            return _arith(op, left, right)
        result = compare_values(left, right)
        if op == "=":
            return result == 0
        if op in ("!=", "<>"):
            return result != 0
        if op == "<":
            return result < 0
        if op == "<=":
            return result <= 0
        if op == ">":
            return result > 0
        if op == ">=":
            return result >= 0
        raise QueryError("unknown operator: %s" % op)
    if isinstance(node, ast.IsNull):
        is_null = evaluate(node.operand, ctx) is None
        return (not is_null) if node.negated else is_null
    if isinstance(node, ast.InList):
        value = evaluate(node.operand, ctx)
        items = [evaluate(item, ctx) for item in node.items]
        if value is None:
            result = None
        else:
            result = False if not items else None
            for item in items:
                if item is None:
                    continue
                if compare_values(value, item) == 0:
                    result = True
                    break
        if result is None:
            return None
        return (not result) if node.negated else result
    if isinstance(node, ast.Between):
        value = evaluate(node.operand, ctx)
        low = evaluate(node.low, ctx)
        high = evaluate(node.high, ctx)
        left = None if (value is None or low is None) else compare_values(low, value) <= 0
        right = None if (value is None or high is None) else compare_values(value, high) <= 0
        if left is False or right is False:
            result = False
        elif left is None or right is None:
            result = None
        else:
            result = True
        if result is None:
            return None
        return (not result) if node.negated else result
    if isinstance(node, ast.Like):
        value = evaluate(node.operand, ctx)
        pattern = evaluate(node.pattern, ctx)
        if value is None or pattern is None:
            return None
        if not isinstance(value, str) or not isinstance(pattern, str):
            raise QueryError("LIKE needs strings")
        result = like(value, pattern)
        return (not result) if node.negated else result
    if isinstance(node, ast.FuncCall):
        if node.name in AGGREGATES:
            try:
                return ctx.aggregates[id(node)]
            except KeyError:
                raise QueryError("aggregate value not computed: %s" % node.name)
        args = [evaluate(arg, ctx) for arg in node.args]
        if node.name == "COALESCE":
            for arg in args:
                if arg is not None:
                    return arg
            return None
        if any(arg is None for arg in args):
            return None
        if node.name == "LOWER":
            return args[0].lower()
        if node.name == "UPPER":
            return args[0].upper()
        if node.name == "LENGTH":
            return len(args[0])
        if node.name == "ABS":
            return abs(args[0])
        if node.name == "ROUND":
            if len(args) == 1:
                return _round_away(args[0])
            places = args[1]
            if not isinstance(places, int) or isinstance(places, bool):
                raise QueryError("ROUND places must be an integer")
            factor = 10.0 ** places
            return _round_away(args[0] * factor) / factor
        raise QueryError("unknown function: %s" % node.name)
    raise QueryError("cannot evaluate %r" % (node,))


def is_aggregate(node):
    return isinstance(node, ast.FuncCall) and node.name in AGGREGATES


def has_aggregate(expression):
    return any(is_aggregate(node) for node in ast.walk(expression))


def iter_aggregates(expression):
    return [node for node in ast.walk(expression) if is_aggregate(node)]


def validate(expression, allow_aggregates=True):
    _validate(expression, allow_aggregates, False)


def _validate(node, allow_aggregates, in_aggregate):
    if isinstance(node, ast.Star):
        raise QueryError("'*' is only valid in COUNT(*)")
    if isinstance(node, ast.FuncCall):
        if node.name in AGGREGATES:
            if not allow_aggregates:
                raise QueryError("aggregate not allowed here: %s" % node.name)
            if in_aggregate:
                raise QueryError("nested aggregate")
            if len(node.args) != 1:
                raise QueryError("%s takes one argument" % node.name)
            argument = node.args[0]
            if isinstance(argument, ast.Star):
                if node.name != "COUNT":
                    raise QueryError("'*' is only valid in COUNT(*)")
                return
            _validate(argument, allow_aggregates, True)
            return
        if node.name not in _SCALAR_ARITY:
            raise QueryError("unknown function: %s" % node.name)
        low, high = _SCALAR_ARITY[node.name]
        if len(node.args) < low or (high is not None and len(node.args) > high):
            raise QueryError("wrong number of arguments for %s" % node.name)
        for argument in node.args:
            _validate(argument, allow_aggregates, in_aggregate)
        return
    for child in ast.child_exprs(node):
        _validate(child, allow_aggregates, in_aggregate)


def compute_aggregate(node, rows):
    if not is_aggregate(node):
        raise QueryError("not an aggregate: %s" % node.name)
    argument = node.args[0]
    if node.name == "COUNT":
        if isinstance(argument, ast.Star):
            return len(rows)
        return sum(
            1
            for row in rows
            if evaluate(argument, EvalContext(columns=row)) is not None
        )
    values = [
        evaluate(argument, EvalContext(columns=row)) for row in rows
    ]
    values = [value for value in values if value is not None]
    if not values:
        return None
    if node.name == "SUM":
        if not all(_number(value) for value in values):
            raise QueryError("SUM of non-numbers")
        if all(isinstance(value, int) for value in values):
            return sum(values)
        return float(sum(values))
    if node.name == "AVG":
        if not all(_number(value) for value in values):
            raise QueryError("AVG of non-numbers")
        return sum(values) / len(values)
    result = values[0]
    for value in values[1:]:
        comparison = compare_values(value, result)
        if node.name == "MIN" and comparison < 0:
            result = value
        elif node.name == "MAX" and comparison > 0:
            result = value
    return result


def _contains_column(node):
    return any(isinstance(sub, ast.ColumnRef) for sub in ast.walk(node))


def check_grouped(expression, group_keys):
    _check_grouped(expression, group_keys)


def _check_grouped(node, group_keys):
    if is_aggregate(node):
        return
    if not has_aggregate(node):
        if _contains_column(node) and ast.expr_key(node) not in group_keys:
            raise QueryError(
                "column is not in GROUP BY: %s" % (node.text or ast.expr_key(node))
            )
        return
    for child in ast.child_exprs(node):
        _check_grouped(child, group_keys)

